import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
    static final int MOD = 1000000007;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());

        if (k == 0) {
            System.out.println(1);
            return;
        }

        int[][][] dp = new int[n + 2][k + 1][n + 2];
        dp[1][0][n + 1] = 1;

        int[] pow2 = new int[n + 2];
        pow2[0] = 1;
        for (int i = 1; i <= n + 1; i++) {
            pow2[i] = (pow2[i - 1] * 2) % MOD;
        }

        for (int i = 1; i <= n; i++) {
            int[][] next = new int[k + 1][n + 2];
            for (int j = 0; j <= k; j++) {
                for (int minR = 1; minR <= n + 1; minR++) {
                    int val = dp[i][j][minR];
                    if (val == 0) continue;

                    int term1 = (long) val * pow2[minR - i] % MOD;
                    next[j][minR] = (next[j][minR] + term1) % MOD;

                    if (j + 1 <= k) {
                        int ways = (pow2[minR - i] - 1 + MOD) % MOD;
                        int term2 = (long) val * ways % MOD;
                        int newMinR = Math.min(minR, i + 1);
                        next[j + 1][newMinR] = (next[j + 1][newMinR] + term2) % MOD;
                    }
                }
            }
            dp[i + 1] = next;
        }

        int ans = 0;
        for (int minR = 1; minR <= n + 1; minR++) {
            ans = (ans + dp[n + 1][k][minR]) % MOD;
        }
        System.out.println(ans);
    }
}
